**What this code covers**

- Heartbeat-based failure detector with gossip propagation.
- Phi-accrual style failure detector with timeout + grace period.
- Each monitor gossips its node state to a random peer periodically.
- Exchange state with a random peer (one round).
- Shared view: node_id -> (version, is_alive)
- Merge: take latest version of each node
- HALF_OPEN: allow one probe
- Node-1 and node-2 keep heartbeating; node-3 dies at t=3

**Defines:** `Node`, `FailureDetector`, `GossipCluster`, `CircuitBreaker`

```python
"""
Heartbeat-based failure detector with gossip propagation.
Models a cluster where each node heartbeats to a monitor,
and failures propagate via gossip between monitors.
"""
import random
import time
from dataclasses import dataclass, field
from typing import Dict, List, Set

@dataclass
class Node:
    node_id: str
    last_heartbeat: float
    is_alive: bool = True
    suspect_count: int = 0

class FailureDetector:
    """Phi-accrual style failure detector with timeout + grace period."""

    def __init__(self, timeout_s: float = 5.0, grace_periods: int = 3):
        self.timeout = timeout_s
        self.grace = grace_periods
        self.nodes: Dict[str, Node] = {}

    def register(self, node_id: str):
        self.nodes[node_id] = Node(node_id=node_id, last_heartbeat=time.time())

    def heartbeat(self, node_id: str):
        if node_id in self.nodes:
            self.nodes[node_id].last_heartbeat = time.time()
            self.nodes[node_id].suspect_count = 0
            self.nodes[node_id].is_alive = True

    def check(self, now: float = None) -> List[str]:
        now = now or time.time()
        newly_dead = []
        for node in self.nodes.values():
            elapsed = now - node.last_heartbeat
            if elapsed > self.timeout:
                node.suspect_count += 1
                if node.suspect_count >= self.grace and node.is_alive:
                    node.is_alive = False
                    newly_dead.append(node.node_id)
            elif not node.is_alive:
                # Node recovered
                node.is_alive = True
                node.suspect_count = 0
        return newly_dead

class GossipCluster:
    """Each monitor gossips its node state to a random peer periodically."""

    def __init__(self, monitor_id: str):
        self.monitor_id = monitor_id
        self.detector = FailureDetector()
        self.peers: List["GossipCluster"] = []
        # shared view: node_id -> (version, is_alive)
        self.view: Dict[str, tuple] = {}

    def add_peer(self, peer: "GossipCluster"):
        self.peers.append(peer)

    def gossip_round(self):
        """Exchange state with a random peer (one round)."""
        if not self.peers:
            return
        peer = random.choice(self.peers)
        # Merge: take latest version of each node
        for node_id, (v, alive) in peer.view.items():
            if node_id not in self.view or self.view[node_id][0] < v:
                self.view[node_id] = (v, alive)
        for node_id, (v, alive) in self.view.items():
            if node_id not in peer.view or peer.view[node_id][0] < v:
                peer.view[node_id] = (v, alive)

class CircuitBreaker:
    """Simple circuit breaker for downstream calls."""

    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failures = 0
        self.state = "CLOSED"  # CLOSED, OPEN, HALF_OPEN
        self.opened_at = 0.0

    def record_success(self):
        self.failures = 0
        self.state = "CLOSED"

    def record_failure(self):
        self.failures += 1
        if self.failures >= self.failure_threshold:
            self.state = "OPEN"
            self.opened_at = time.time()

    def can_call(self) -> bool:
        if self.state == "CLOSED":
            return True
        if self.state == "OPEN":
            if time.time() - self.opened_at > self.recovery_timeout:
                self.state = "HALF_OPEN"
                return True
            return False
        # HALF_OPEN: allow one probe
        return True

if __name__ == "__main__":
    random.seed(42)
    fd = FailureDetector(timeout_s=2.0, grace_periods=2)
    for nid in ["node-1", "node-2", "node-3"]:
        fd.register(nid)

    print("=== Failure Detector Simulation ===")
    t = 0.0
    while t < 10.0:
        # node-1 and node-2 keep heartbeating; node-3 dies at t=3
        fd.heartbeat("node-1")
        fd.heartbeat("node-2")
        if t < 3.0:
            fd.heartbeat("node-3")

        now = time.time() + t
        dead = fd.check(now=now)
        if dead:
            print(f"t={t:.1f}s: marked dead: {dead}")

        alive = [n.node_id for n in fd.nodes.values() if n.is_alive]
        print(f"t={t:.1f}s: alive={alive}")
        t += 1.0

    print("\n=== Circuit Breaker Simulation ===")
    cb = CircuitBreaker(failure_threshold=3, recovery_timeout=2.0)
    for i in range(10):
        if cb.can_call():
            try:
                # simulate downstream failure
                cb.record_failure()
                print(f"call {i}: state={cb.state} failures={cb.failures}")
            except Exception:
                pass
        else:
            print(f"call {i}: REJECTED (circuit OPEN)")
        time.sleep(0.6)

    print(f"\nFinal circuit state: {cb.state}")
